sp_widget.client_script:
api.controller = function($location) {

    var c = this;

    c.otp = "";
    c.verifying = false;
    c.errorMessage = "";
    c.successMessage = "";

    c.verifyOTP = function() {

        c.errorMessage = "";
        c.successMessage = "";

        if (!c.otp || !/^\d{6}$/.test(c.otp)) {
            c.errorMessage = "Please enter any 6-digit number.";
            return;
        }

        var params = $location.search();
        var claimSysId = params.sys_id || "";

        if (!claimSysId) {
            c.errorMessage = "Claim information is missing.";
            return;
        }

        c.verifying = true;

        c.server.get({
            action: "verify_otp",
            otp: c.otp,
            claim_sys_id: claimSysId
        }).then(function(response) {

            c.verifying = false;

            if (response.data.success === true) {

                c.successMessage =
                    "OTP verified successfully.";

                setTimeout(function() {

                    $location.search({
                        id: "documents",
                        sys_id: claimSysId
                    });

                }, 1500);

            } else {

                c.errorMessage =
                    response.data.message ||
                    "OTP verification failed.";

            }

        }, function() {

            c.verifying = false;

            c.errorMessage =
                "Unable to process OTP.";

        });

    };

};

sp_widget.css:
.otp-container {
    min-height: 70vh;
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 30px;
    background: #f4f8fc;
}

.otp-card {
    width: 450px;
    background: white;
    padding: 40px;
    border-radius: 12px;
    text-align: center;
    box-shadow: 0 5px 20px rgba(0,0,0,0.08);
}

.otp-icon {
    font-size: 42px;
    margin-bottom: 15px;
}

.otp-card h1 {
    color: #183b67;
    margin-bottom: 10px;
}

.otp-subtitle {
    color: #6c757d;
    margin-bottom: 25px;
}

.otp-info {
    background: #eef6ff;
    border-left: 4px solid #0d6efd;
    padding: 15px;
    text-align: left;
    margin-bottom: 25px;
}

.otp-info p {
    margin: 5px 0 0;
}

.otp-card label {
    display: block;
    text-align: left;
    font-weight: 600;
    margin-bottom: 8px;
}

.otp-input {
    width: 100%;
    padding: 14px;
    text-align: center;
    font-size: 22px;
    letter-spacing: 6px;
    border: 1px solid #ccd4dd;
    border-radius: 6px;
    box-sizing: border-box;
}

.verify-btn {
    width: 100%;
    margin-top: 20px;
    padding: 13px;
    border: none;
    border-radius: 6px;
    background: #0d6efd;
    color: white;
    font-weight: 600;
    cursor: pointer;
}

.error-message {
    margin-top: 15px;
    padding: 10px;
    background: #fdecec;
    color: #a52834;
}

.success-message {
    margin-top: 15px;
    padding: 10px;
    background: #e8f7ee;
    color: #18733c;
}

