(function() {

    data.success = false;
    data.message = "";

    if (input && input.action == "verify_otp") {

        var enteredOTP = String(input.otp || "").trim();
        var claimSysId = String(input.claim_sys_id || "").trim();

        if (!enteredOTP || !/^\d{6}$/.test(enteredOTP)) {
            data.message = "Please enter any 6-digit number.";
            return;
        }

        if (claimSysId) {

            var claim = new GlideRecord("x_snc_insurance_0_claim");

            if (claim.get(claimSysId)) {

                claim.setValue("otp_entered", enteredOTP);
                claim.setValue("otp_verified", true);
                claim.update();

            }
        }

        data.success = true;
        data.message = "OTP verified successfully.";

    }

})();
